from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    for color in set(v for row in grid for v in row) - {bg}:
        # Prefix sums let us find rectangles containing this color and no background.
        pcolor = [[0] * (w + 1) for _ in range(h + 1)]
        pbg = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            sc = sb = 0
            for c in range(w):
                sc += grid[r][c] == color
                sb += grid[r][c] == bg
                pcolor[r + 1][c + 1] = pcolor[r][c + 1] + sc
                pbg[r + 1][c + 1] = pbg[r][c + 1] + sb
        candidates = []
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        area = (r1-r0+1) * (c1-c0+1)
                        count = pcolor[r1+1][c1+1] - pcolor[r0][c1+1] - pcolor[r1+1][c0] + pcolor[r0][c0]
                        bg_count = pbg[r1+1][c1+1] - pbg[r0][c1+1] - pbg[r1+1][c0] + pbg[r0][c0]
                        if bg_count == 0 and count / area >= 0.80:
                            candidates.append((r0,r1,c0,c1))
        maximal = []
        for a in candidates:
            r0,r1,c0,c1 = a
            if not any(b[0] <= r0 and b[1] >= r1 and b[2] <= c0 and b[3] >= c1 and b != a for b in candidates):
                maximal.append(a)
        for r0,r1,c0,c1 in maximal:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    out[r][c] = color
    return out
